import java.util.*;

public class Main {
    /** 依赖优先的构建顺序：pending[m] = m 尚未完成的 reactor 内依赖数 */
    static List<String> buildOrder(List<String> mods, Map<String, List<String>> deps) {
        Map<String, Integer> pending = new LinkedHashMap<>();
        for (String m : mods) {
            int c = 0;
            for (String d : deps.getOrDefault(m, List.of())) if (mods.contains(d)) c++;
            pending.put(m, c);
        }
        // 反向邻接：谁依赖我 -> 我先建好之后才能轮到它
        Map<String, List<String>> rev = new LinkedHashMap<>();
        for (String m : mods) rev.put(m, new ArrayList<>());
        for (Map.Entry<String, List<String>> e : deps.entrySet())
            for (String d : e.getValue()) if (rev.containsKey(d)) rev.get(d).add(e.getKey());

        Deque<String> ready = new ArrayDeque<>();
        for (String m : mods) if (pending.get(m) == 0) ready.add(m);

        List<String> order = new ArrayList<>();
        while (!ready.isEmpty()) {
            String cur = ready.poll();
            order.add(cur);
            for (String dependent : rev.get(cur))
                if (pending.merge(dependent, -1, Integer::sum) == 0) ready.add(dependent);
        }
        return order;
    }

    public static void main(String[] args) {
        List<String> mods = List.of("common", "dao", "service", "web", "gateway");
        Map<String, List<String>> deps = new LinkedHashMap<>();
        deps.put("dao", List.of("common"));
        deps.put("service", List.of("dao", "common"));
        deps.put("web", List.of("service"));
        deps.put("gateway", List.of("common"));

        System.out.println("=== declared <modules> order ===");
        System.out.println("  " + mods);
        System.out.println();
        System.out.println("=== intra-reactor dependencies (module -> what it needs) ===");
        deps.forEach((k, v) -> System.out.println("  " + k + " -> " + v));

        List<String> order = buildOrder(mods, deps);
        System.out.println();
        System.out.println("=== reactor build order (dependencies first) ===");
        for (int i = 0; i < order.size(); i++) System.out.println("  " + (i + 1) + ". " + order.get(i));
        System.out.println("  modules built = " + order.size() + " / " + mods.size());
        System.out.println("  note: 'gateway' jumped ahead of 'service'/'web' because it only needs 'common'");

        System.out.println();
        System.out.println("=== now add a cycle: common -> web ===");
        Map<String, List<String>> cyc = new LinkedHashMap<>(deps);
        cyc.put("common", List.of("web"));
        cyc.forEach((k, v) -> System.out.println("  " + k + " -> " + v));
        List<String> bad = buildOrder(mods, cyc);
        System.out.println("  modules built = " + bad.size() + " / " + mods.size());
        System.out.println("  reason: every module has at least one unfinished dependency");
        System.out.println("  maven would fail with: the projects in the reactor contain a cyclic reference");
    }
}
